def trench_map(w,h,title,cap,labels):
    b=f'<rect x="5" y="5" width="{w-10}" height="{h-10}" fill="#fff" stroke="#111" stroke-width="2"/>'+T(w-70,32,title,17,'middle',700)
    b+='<path d="M120 80 Q220 40 330 70 Q360 100 320 120 Q200 110 120 80Z" fill="#d9d0b8" stroke="#555" stroke-width="2"/>'
    b+='<path d="M120 190 Q150 150 230 160 Q290 160 330 200 L300 250 Q220 240 120 190Z" fill="none" stroke="#111" stroke-width="2"/>'
    b+='<path d="M140 210 Q150 330 210 400" fill="none" stroke="#111" stroke-width="4" stroke-dasharray="6 3"/>'
    b+='<path d="M140 210 Q200 150 260 165 Q330 175 350 230" fill="none" stroke="#111" stroke-width="4" stroke-dasharray="6 3"/>'
    b+='<ellipse cx="235" cy="195" rx="40" ry="16" fill="#e9e1c8" stroke="#555"/>'
    b+='<rect x="240" y="300" width="50" height="30" fill="none" stroke="#111" stroke-width="2"/>'
    b+='<ellipse cx="170" cy="440" rx="60" ry="14" fill="#d9d0b8" stroke="#555"/>'
    b+='<g stroke="#2a6" stroke-width="2"><line x1="250" y1="355" x2="250" y2="372"/><line x1="270" y1="360" x2="270" y2="377"/><line x1="290" y1="352" x2="290" y2="369"/></g>'
    b+='<g stroke="#111" stroke-width="2"><line x1="410" y1="110" x2="410" y2="150"/><line x1="390" y1="130" x2="430" y2="130"/></g>'
    for x,y,t in labels: b+=T(x,y,t,12,'middle',700)
    return svg(w,h,cap,b)
def plan2(w,h,title,cap,labels):
    b=f'<rect x="5" y="5" width="{w-10}" height="{h-10}" fill="#fff" stroke="#111" stroke-width="2"/>'+T(w-80,32,title,17,'middle',700)
    b+='<path d="M200 50 Q170 200 120 300 Q80 380 60 470" fill="none" stroke="#111" stroke-width="2"/>'
    b+='<path d="M200 50 Q300 100 380 150" fill="none" stroke="#111" stroke-width="2"/>'
    b+='<path d="M240 170 Q320 110 360 120 Q320 140 280 190Z" fill="#d9d0b8" stroke="#555"/>'
    b+='<path d="M230 260 L290 200 L310 215 L260 275Z" fill="#fff" stroke="#111" stroke-width="3"/>'
    b+='<path d="M250 290 L330 350 L350 380 L330 390 L240 310Z" fill="#fff" stroke="#111" stroke-width="3"/>'
    b+='<path d="M180 390 Q250 470 300 410" fill="none" stroke="#111" stroke-width="2"/>'
    b+='<ellipse cx="225" cy="455" rx="50" ry="14" fill="#ccc" stroke="#555"/>'
    b+='<path d="M30 400 Q80 410 140 440 M30 420 Q80 430 140 460 M30 440 Q80 450 140 480" fill="none" stroke="#555" stroke-width="2"/>'
    for x,y,t in labels: b+=T(x,y,t,11,'middle',700)
    return svg(w,h,cap,b)
